export interface DedicatedEndpointApproval {
  organizationId: string;
  projectId: string;
  region: 'fr-par';
  deploymentId: string;
  endpointId: string;
  endpointUrl: string;
  modelName: string;
  authentication: 'iam' | 'disabled';
