  | 'invalid_scope'
  | 'not_ready'
  | 'invalid_model'
  | 'invalid_approval'
  | 'expired_approval'
  | 'endpoint_unavailable'
  | 'private_or_unknown_network'
  | 'unsafe_endpoint'
  | 'approval_mismatch'
  | 'unauthenticated_not_approved';
